static int js_pi_script_utf16_position(const JSNativeScript *script, int offset)
{
    const uint8_t *p, *end, *next;
    int units = 0, c;
    if (!script || offset < 0 || offset > script->input_length)
        return -1;
    p = script->input;
    end = p + offset;
    while (p < end) {
        c = utf8_decode_len(p, end - p, &next);
        if (c < 0 || next <= p || next > end)
            return -1;
        units += c > 0xffff ? 2 : 1;
        p = next;
    }
    return units;
}

